//! Checks by body kind (solid, sheet, wire) and the constructions shared by the SMLib sweeps and
//! primitives suites (`smlib_sweeps`, `smlib_primitives`, generated by `tools/smlib_to_rust.py`).
//! Not part of `smlib_common` itself (the other suites don't need it): a suite includes it with
//! `#[path = "smlib_common/kinds.rs"] mod kinds;`.
//!
//! SMLib builds these models in code (`SmTopologySweep`, `SmPrimitiveCreation`), often as one
//! non-manifold cell complex holding faces, wire edges and vertex shells together. The cases
//! build the cadrs equivalent of each piece with the kernel's own operations (extrude, revolve,
//! sweep, loft, booleans, and the draw harness's `prism`/`revol` for vertices and edges) and
//! check each piece by its kind. Wires and points are Phase 1b (body kinds): a vertex swept is
//! a wire body (`Kernel::sweep_body`), an edge or wire swept a sheet.
#![allow(dead_code)]

use cadrs_kernel::native::draw::Shape;
use cadrs_kernel::native::features::prism_along;
use cadrs_kernel::native::math::{P3, V3};
use cadrs_kernel::native::topo::Body;
use cadrs_kernel::native::NativeKernel;
use cadrs_kernel::{Axis, BodyId, BoolOp, Curve2, Extent, Kernel, KernelError, Loop, Motion, OpResult, Plane, Profile, Region};
use nalgebra::{Point2, Unit};

use super::{check_result, edge_count, invalid, Expect, REL_TOL};

/// What a result is.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Kind {
    Solid,
    /// Faces whose shells are open, no solid.
    Sheet,
    /// Edges only.
    Wire,
}

/// What a result must be: its kind and the values to check (`None` isn't checked). Counts are
/// given only for results without closed (periodic) faces: kernels place seams and split
/// periodic faces differently.
#[derive(Debug, Clone, Copy)]
pub struct Want {
    pub kind: Kind,
    pub faces: Option<usize>,
    pub edges: Option<usize>,
    pub volume: Option<f64>,
    pub area: Option<f64>,
    /// A wire's total length.
    pub length: Option<f64>,
}

pub const SOLID: Want = Want { kind: Kind::Solid, faces: None, edges: None, volume: None, area: None, length: None };
pub const SHEET: Want = Want { kind: Kind::Sheet, ..SOLID };
pub const WIRE: Want = Want { kind: Kind::Wire, ..SOLID };

pub fn kerr(e: KernelError) -> String {
    format!("{e:?}")
}

fn near(what: &str, ours: f64, want: Option<f64>) -> Result<(), String> {
    let Some(t) = want else { return Ok(()) };
    let rel = (ours - t).abs() / t.abs().max(1e-9);
    if rel <= REL_TOL {
        Ok(())
    } else {
        Err(format!("{what} {ours:.6}, want {t:.6} ({rel:.1e} off)"))
    }
}

fn counts(b: &Body, w: &Want) -> Result<(), String> {
    if let Some(n) = w.faces {
        if b.faces.len() != n {
            return Err(format!("{} faces, want {n}", b.faces.len()));
        }
    }
    if let Some(n) = w.edges {
        if edge_count(b) != n {
            return Err(format!("{} edges, want {n}", edge_count(b)));
        }
    }
    Ok(())
}

/// The total length of a body's edges.
fn edges_length(b: &Body) -> f64 {
    b.edges.iter().filter(|e| !e.degenerate).map(|e| e.curve.length(e.t[0].min(e.t[1]), e.t[0].max(e.t[1]))).sum()
}

/// Checks a body against `w`: valid (the full check), of the kind, and `w`'s values.
pub fn check_body(k: &NativeKernel, id: BodyId, w: &Want) -> Result<(), String> {
    let b = k.get(id).map_err(kerr)?;
    match w.kind {
        Kind::Solid => check_result(b, b, &Expect { volume: w.volume, area: w.area, solid: Some(true), ..Expect::default() })?,
        Kind::Sheet => {
            if let Some(i) = invalid(b) {
                return Err(i);
            }
            if !b.solids.is_empty() || b.faces.is_empty() || b.shells.iter().all(|s| s.closed) {
                return Err(format!("not a sheet ({} solids, {} faces)", b.solids.len(), b.faces.len()));
            }
            near("area", cadrs_kernel::native::mass::body_mass(b).surface_area, w.area)?;
        }
        Kind::Wire => {
            if let Some(i) = invalid(b) {
                return Err(i);
            }
            if !b.faces.is_empty() {
                return Err(format!("not a wire: {} faces", b.faces.len()));
            }
            near("length", edges_length(b), w.length)?;
        }
    }
    counts(b, w)
}

/// A wire result of the draw harness: an edge, a wire, a wire body, or a compound of them.
/// (edges, length).
fn wire_of(k: &NativeKernel, s: &Shape) -> Result<(usize, f64), String> {
    Ok(match s {
        Shape::Edge(e) => (1, e.length()),
        Shape::Wire(w) => (w.len(), w.iter().map(|e| e.length()).sum()),
        Shape::Body(b) => {
            let b = k.get(*b).map_err(kerr)?;
            if !b.faces.is_empty() {
                return Err(format!("not a wire: {} faces", b.faces.len()));
            }
            (edge_count(b), edges_length(b))
        }
        Shape::Compound(v) => {
            let mut acc = (0, 0.0);
            for x in v {
                let (n, l) = wire_of(k, x)?;
                acc = (acc.0 + n, acc.1 + l);
            }
            acc
        }
        other => return Err(format!("not a wire: {other:?}")),
    })
}

/// Checks a wire result against `w` (edges and length).
pub fn check_wire(k: &NativeKernel, s: &Shape, w: &Want) -> Result<(), String> {
    let (n, l) = wire_of(k, s)?;
    if let Some(want) = w.edges {
        if n != want {
            return Err(format!("{n} edges, want {want}"));
        }
    }
    near("length", l, w.length)
}

/// The one body of a result.
pub fn one(r: OpResult) -> Result<BodyId, String> {
    match r.bodies.as_slice() {
        [b] => Ok(*b),
        v => Err(format!("{} bodies", v.len())),
    }
}

/// A body of the draw harness.
pub fn body_of(s: Shape) -> Result<BodyId, String> {
    match s {
        Shape::Body(b) => Ok(b),
        other => Err(format!("not a body: {other:?}")),
    }
}

/// How SMLib's sweep moves things (`SmTranslationalSweepGeometry`,
/// `SmRotationalSweepGeometry`).
#[derive(Debug, Clone, Copy)]
pub enum Move {
    Trans([f64; 3]),
    /// About the axis through `o` along `d`, by `deg` degrees (counter-clockwise seen from the
    /// tip of `d`).
    Rot { o: [f64; 3], d: [f64; 3], deg: f64 },
}

impl Move {
    pub fn axis(&self) -> Option<Axis> {
        match *self {
            Move::Rot { o, d, .. } => Some(Axis { origin: P3::from(o), dir: Unit::new_normalize(V3::from(d)) }),
            Move::Trans(_) => None,
        }
    }

    pub fn full(&self) -> bool {
        matches!(*self, Move::Rot { deg, .. } if deg >= 360.0 - 1e-9)
    }

    pub fn motion(&self) -> Motion {
        match *self {
            Move::Trans(v) => Motion::translation(V3::from(v)),
            Move::Rot { deg, .. } => Motion::rotation(&self.axis().expect("a rotation"), deg.to_radians()),
        }
    }

    /// A shape of the draw harness swept (`prism`, `revol`).
    pub fn sweep(&self, k: &mut NativeKernel, s: &Shape) -> Result<Shape, String> {
        match *self {
            Move::Trans(v) => k.prism(s, v[0], v[1], v[2]),
            Move::Rot { o, d, deg } => k.revol(s, o[0], o[1], o[2], d[0], d[1], d[2], deg.min(360.0)),
        }
        .map_err(kerr)
    }

    /// A shape of the draw harness moved.
    pub fn apply(&self, k: &mut NativeKernel, s: &Shape) -> Result<Shape, String> {
        match *self {
            Move::Trans(v) => k.ttranslate(s, v[0], v[1], v[2]),
            Move::Rot { o, d, deg } => k.trotate(s, o[0], o[1], o[2], d[0], d[1], d[2], deg),
        }
        .map_err(kerr)
    }

    /// A planar profile swept into a solid: an extrude (along the normal), a prism (along
    /// another direction) or a revolve.
    pub fn sweep_profile(&self, k: &mut NativeKernel, p: &Profile) -> Result<BodyId, String> {
        let r = match *self {
            Move::Trans(v) => {
                let v = V3::from(v);
                let along = v.dot(&p.plane.normal);
                if (v - p.plane.normal.into_inner() * along).norm() <= 1e-12 * v.norm() {
                    k.extrude(p, Extent::Blind(along))
                } else {
                    prism_along(k, p, v)
                }
            }
            Move::Rot { deg, .. } => k.revolve(p, self.axis().expect("a rotation"), deg.min(360.0).to_radians()),
        };
        one(r.map_err(kerr)?)
    }
}

/// Points swept `reps` times each (SMLib's vertices swept into edges, `SetRepetitions`): the
/// draw harness's `prism`/`revol` of a vertex, again from where the last one ended.
pub fn point_sweeps(k: &mut NativeKernel, pts: &[[f64; 3]], m: Move, reps: usize) -> Result<Shape, String> {
    let mut out = Vec::new();
    for p in pts {
        let mut at = Shape::Vertex(P3::from(*p));
        for _ in 0..reps {
            out.push(m.sweep(k, &at)?);
            at = m.apply(k, &at)?;
        }
    }
    Ok(Shape::Compound(out))
}

/// SMLib's `CreateCylindricalBox(len, r_in, r_out, a0, a1)` (angles in degrees, about the world
/// z from x): cadrs's `Kernel::cylindrical_box`.
pub fn cylindrical_box_deg(k: &mut NativeKernel, len: f64, r_in: f64, r_out: f64, a0: f64, a1: f64) -> Result<BodyId, KernelError> {
    let spec = cadrs_kernel::CylindricalBox { frame: Plane::top(), length: len, inner_radius: r_in, outer_radius: r_out, start_angle: a0.to_radians(), end_angle: a1.to_radians() };
    Ok(k.cylindrical_box(&spec)?.bodies[0])
}

/// A line in plane coordinates.
pub fn seg(a: [f64; 2], b: [f64; 2]) -> Curve2 {
    Curve2::Line { a: Point2::new(a[0], a[1]), b: Point2::new(b[0], b[1]), source: None }
}

/// A closed polygon.
pub fn polygon(pts: &[[f64; 2]]) -> Loop {
    Loop { curves: (0..pts.len()).map(|i| seg(pts[i], pts[(i + 1) % pts.len()])).collect() }
}

/// A whole circle.
pub fn circle(c: [f64; 2], r: f64) -> Loop {
    Loop { curves: vec![Curve2::Circle { center: Point2::new(c[0], c[1]), radius: r, source: None }] }
}

pub fn region(outer: Loop, holes: Vec<Loop>) -> Region {
    Region { outer, holes, source: None }
}

/// The plane through `o` with axes `x` and `y` (made orthonormal).
pub fn plane(o: [f64; 3], x: [f64; 3], y: [f64; 3]) -> Plane {
    let x = V3::from(x).normalize();
    let n = x.cross(&V3::from(y)).normalize();
    Plane { origin: P3::from(o), x_dir: Unit::new_normalize(x), normal: Unit::new_normalize(n) }
}

/// A solid of several pieces united (one boolean with all the tools).
pub fn unite(k: &mut NativeKernel, pieces: &[BodyId]) -> Result<BodyId, String> {
    match pieces {
        [] => Err("nothing to unite".into()),
        [one_body] => Ok(*one_body),
        [first, rest @ ..] => one(k.boolean(BoolOp::Union, *first, rest).map_err(kerr)?),
    }
}
